mapper.select:
SELECT STATUS
FROM USERS
WHERE USER_ID = #{userId}

mapper.update:
UPDATE CMM_CODE
COM_CD_NM = #{comCdNm, jdbcType=VARCHAR}, USE_YN = #{useYn, jdbcType=VARCHAR}, SORT_SEQ = #{sortSeq, jdbcType=NUMERIC}, MOD_ID = #{modId, jdbcType=VARCHAR}, MOD_DT = SYSDATE
WHERE COM_CD_ID = #{comCdId, jdbcType=VARCHAR}

UPDATE CMM_CODE_DTL
DTL_CD_NM = #{dtlCdNm, jdbcType=VARCHAR}, DTL_CD_EXPLN = #{dtlCdExpln, jdbcType=VARCHAR}, LNKG_DTL_CD_ID1 = #{lnkgDtlCdId1, jdbcType=VARCHAR}, LNKG_DTL_CD_NM1 = #{lnkgDtlCdNm1, jdbcType=VARCHAR}, LNKG_DTL_CD_ID2 = #{lnkgDtlCdId2, jdbcType=VARCHAR}, LNKG_DTL_CD_NM2 = #{lnkgDtlCdNm2, jdbcType=VARCHAR}, USE_YN = #{useYn, jdbcType=VARCHAR}, SORT_SEQ = #{sortSeq, jdbcType=NUMERIC}, MOD_ID = #{modId, jdbcType=VARCHAR}, MOD_DT = SYSDATE
WHERE COM_CD_ID = #{comCdId, jdbcType=VARCHAR} AND DTL_CD_ID = #{dtlCdId, jdbcType=VARCHAR}

UPDATE CMM_CODE_DTL
SET USE_YN = 'N',
    MOD_ID = #{modId, jdbcType=VARCHAR},
    MOD_DT = SYSDATE
WHERE COM_CD_ID = #{comCdId, jdbcType=VARCHAR}
  AND DTL_CD_ID = #{dtlCdId, jdbcType=VARCHAR}
